        function createCard(agentData) {
            const card = document.createElement('div');
            card.className = 'friction-card';
            card.dataset.agent = agentData.agent;
            card.dataset.frScore = agentData.fr_score;
            card.dataset.compatibilityScore = agentData.compatibility_score;

            const agentName = document.createElement('h3');
            agentName.textContent = agentData.agent;
            card.appendChild(agentName);

            const frScore = document.createElement('p');
            frScore.innerHTML = `Data Friction (FR) Score: <span class="fr_score">${agentData.fr_score.toFixed(2)}</span>`;
            card.appendChild(frScore);

            const compatibilityScore = document.createElement('p');
            let compatHtml = 'Compatibility Score: ';
            if (compatData[agentData.agent]) {
                const bestPartner = Object.keys(compatData[agentData.agent]).reduce((a, b) => compatData[agentData.agent][a] > compatData[agentData.agent][b] ? a : b);
                compatHtml += `<strong>${bestPartner}</strong> (${compatData[agentData.agent][bestPartner].toFixed(2)})`;
            } else {
                compatHtml += 'N/A';
            }
            compatibilityScore.innerHTML = compatHtml;
            card.appendChild(compatibilityScore);

            return card;
        }

        function renderCards(sortOrder) {
            const container = document.getElementById('friction-grid');
            container.innerHTML = '';

            let sortedData = [...frictionData];

            switch (sortOrder) {
                case 'fr_score_desc':
                    sortedData.sort((a, b) => b.fr_score - a.fr_score);
                    break;
                case 'fr_score_asc':
                    sortedData.sort((a, b) => a.fr_score - b.fr_score);
                    break;
                case 'compatibility_score_desc':
                    sortedData.sort((a, b) => {
                        const scoreA = compatData[a.agent] ? Math.max(...Object.values(compatData[a.agent])) : -1;
                        const scoreB = compatData[b.agent] ? Math.max(...Object.values(compatData[b.agent])) : -1;
                        return scoreB - scoreA;
                    });
                    break;
                case 'compatibility_score_asc':
                    sortedData.sort((a, b) => {
                        const scoreA = compatData[a.agent] ? Math.max(...Object.values(compatData[a.agent])) : -1;
                        const scoreB = compatData[b.agent] ? Math.max(...Object.values(compatData[b.agent])) : -1;
                        return scoreA - scoreB;
                    });
                    break;
                case 'alphabetical_asc':
                    sortedData.sort((a, b) => a.agent.localeCompare(b.agent));
                    break;
                case 'alphabetical_desc':
                    sortedData.sort((a, b) => b.agent.localeCompare(a.agent));
                    break;
            }

            sortedData.forEach(agent => {
                const card = createCard(agent);
                container.appendChild(card);
            });
        }

        function sortCards() {
            const sortOrder = document.getElementById('sortOptions').value;
            renderCards(sortOrder);
        }

        // Initial render
        renderCards('fr_score_desc');
    </script>
